function edit(t){if(!permitted(t))return;const d=q(shared?'#sharedDialog':'#details'),root=q(shared?'#sharedDetail':'#detailBody');document.body.classList.remove('task-drawer-open');if(shared)selectedTask=null;else selectedRichTask=null;root.innerHTML='<div class="shared-task-head"><h2>ویرایش کار</h2><button class="secondary" type="button" id="cancelTaskEdit">انصراف</button></div><form id="taskEditForm"><label>عنوان کار<input name="title" required maxlength="200" value="'+esc(t.title)+'"></label><label>شرح کار<textarea name="description" rows="4" maxlength="10000">'+esc(t.description||'')+'</textarea></label><label>مهلت انجام<input type="date" name="due" value="'+esc(t.due||'')+'"></label><p class="shared-meta">'+(['review','done','آماده بررسی','بسته‌شده'].includes(t.status)?'با ذخیرهٔ تغییرات، کار دوباره باز می‌شود؛ فایل‌ها و سوابق قبلی حفظ می‌شوند.':'مسئول و همکارها از بخش ارجاع، توسط مدیریت تغییر می‌کنند.')+'</p><button class="primary">ذخیره تغییرات</button></form>';if(!d.open)d.showModal();q('#cancelTaskEdit').onclick=()=>{d.close();detail(t.id)};q('#taskEditForm').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button'),f=new FormData(e.target);b.disabled=true;try{if(shared){await rpc('sm_edit_task',{p_task:t.id,p_revision:t.revision,p_title:f.get('title').trim(),p_description:f.get('description').trim(),p_due:f.get('due')||null});await refresh()}else{if(!permitted(t)||!tasks.includes(t))throw Error('کار تغییر کرده؛ تازه‌سازی کنید.');invalidateReview(t);if(t.status==='بسته‌شده'){t.status='در حال انجام';t.completed=null;t.reviewSubmission=null}Object.assign(t,{title:f.get('title').trim(),description:f.get('description').trim(),due:f.get('due')||''});stateLog(t,'عنوان، شرح یا مهلت کار ویرایش شد.');notifyTask(t,[t.owner,t.assignedBy,...(t.collaborators||[])],'ویرایش کار: '+t.title);save()}d.close();await detail(t.id);(shared?message:toast)('تغییرات ذخیره شد.')}catch(err){(shared?message:toast)(shared?failure(err):err.message)}finally{b.disabled=false}}}
function buttons(){const area=q(shared?'#sharedContent':'#workspace');if(!area)return;area.querySelectorAll('[data-task],[data-shared-card]').forEach(title=>{const t=tasks.find(x=>x.id===(title.dataset.task||title.dataset.sharedCard)),row=title.closest('tr,.desk-task-card');if(!t||!permitted(t)||!row||row.querySelector('.task-row-edit'))return;const b=document.createElement('button');b.type='button';b.className='task-row-edit';b.textContent='ویرایش';b.setAttribute('aria-label','ویرایش کار: '+t.title);b.onclick=e=>{e.preventDefault();e.stopPropagation();edit(t)};(row.matches('tr')?row.lastElementChild:row).prepend(b)})}
const oldTasks=renderTasks;renderTasks=function(...a){const result=oldTasks(...a);buttons();return result};const oldRender=render;render=function(...a){const result=oldRender(...a);buttons();return result};const oldDetail=detail;detail=async function(id,...a){await oldDetail(id,...a);const t=tasks.find(t=>t.id===id),root=q(shared?'#sharedDetail':'#detailBody');if(!t||!permitted(t)||!q(shared?'#sharedDialog':'#details')?.open||!root)return;root.querySelector('#editTaskDirect')?.remove();const b=document.createElement('button');b.id='editTaskDirect';b.type='button';b.className='task-row-edit';b.textContent='ویرایش کار';b.onclick=()=>edit(t);root.querySelector('.shared-task-head,.dialog-head')?.after(b)};buttons();
